class Solution {
    public java.util.List<String> fullJustify(String[] words, int maxWidth) {
        java.util.List<String> result = new java.util.ArrayList<>();
        int start = 0;
        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }

            int gaps = end - start - 1;
            StringBuilder line = new StringBuilder();
            if (end == words.length || gaps == 0) {
                for (int i = start; i < end; i++) {
                    if (i > start) {
                        line.append(' ');
                    }
                    line.append(words[i]);
                }
                appendSpaces(line, maxWidth - line.length());
            } else {
                int totalSpaces = maxWidth - letters;
                int base = totalSpaces / gaps;
                int extra = totalSpaces % gaps;
                for (int i = start; i < end; i++) {
                    if (i > start) {
                        appendSpaces(line, base + (i - start <= extra ? 1 : 0));
                    }
                    line.append(words[i]);
                }
            }
            result.add(line.toString());
            start = end;
        }
        return result;
    }

    private void appendSpaces(StringBuilder builder, int count) {
        for (int i = 0; i < count; i++) {
            builder.append(' ');
        }
    }
}

class Solution {
    public java.util.List<String> fullJustify(String[] words, int maxWidth) {
        java.util.List<String> result = new java.util.ArrayList<>();
        int start = 0;
        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }

            boolean lastLine = end == words.length;
            int gaps = end - start - 1;
            int[] spaces = new int[Math.max(1, gaps)];
            if (lastLine || gaps == 0) {
                java.util.Arrays.fill(spaces, 1);
            } else {
                int totalSpaces = maxWidth - letters;
                java.util.Arrays.fill(spaces, totalSpaces / gaps);
                for (int i = 0; i < totalSpaces % gaps; i++) {
                    spaces[i]++;
                }
            }

            StringBuilder line = new StringBuilder();
            for (int i = start; i < end; i++) {
                line.append(words[i]);
                if (i < end - 1) {
                    for (int s = 0; s < spaces[i - start]; s++) {
                        line.append(' ');
                    }
                }
            }
            while (line.length() < maxWidth) {
                line.append(' ');
            }
            result.add(line.toString());
            start = end;
        }
        return result;
    }
}

class Solution {
    public java.util.List<String> fullJustify(String[] words, int maxWidth) {
        java.util.List<String> result = new java.util.ArrayList<>();
        int start = 0;
        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }

            char[] line = new char[maxWidth];
            java.util.Arrays.fill(line, ' ');
            boolean lastLine = end == words.length;
            int gaps = end - start - 1;
            int base = 1;
            int extra = 0;
            if (!lastLine && gaps > 0) {
                int totalSpaces = maxWidth - letters;
                base = totalSpaces / gaps;
                extra = totalSpaces % gaps;
            }

            int pos = 0;
            for (int i = start; i < end; i++) {
                String word = words[i];
                for (int c = 0; c < word.length(); c++) {
                    line[pos++] = word.charAt(c);
                }
                if (i < end - 1) {
                    pos += base + (i - start < extra ? 1 : 0);
                }
            }
            result.add(new String(line));
            start = end;
        }
        return result;
    }
}

class Solution {
    public java.util.List<String> fullJustify(String[] words, int maxWidth) {
        java.util.List<int[]> ranges = new java.util.ArrayList<>();
        java.util.List<Integer> letterCounts = new java.util.ArrayList<>();
        int start = 0;
        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }
            ranges.add(new int[] {start, end});
            letterCounts.add(letters);
            start = end;
        }

        java.util.List<String> result = new java.util.ArrayList<>();
        for (int i = 0; i < ranges.size(); i++) {
            int[] range = ranges.get(i);
            boolean lastLine = i == ranges.size() - 1;
            result.add(renderLine(words, range[0], range[1], letterCounts.get(i), maxWidth, lastLine));
        }
        return result;
    }

    private String renderLine(String[] words, int start, int end, int letters, int maxWidth, boolean lastLine) {
        int gaps = end - start - 1;
        StringBuilder line = new StringBuilder();
        if (lastLine || gaps == 0) {
            for (int i = start; i < end; i++) {
                if (i > start) {
                    line.append(' ');
                }
                line.append(words[i]);
            }
        } else {
            int totalSpaces = maxWidth - letters;
            int base = totalSpaces / gaps;
            int extra = totalSpaces % gaps;
            for (int i = start; i < end; i++) {
                if (i > start) {
                    for (int s = 0; s < base + (i - start <= extra ? 1 : 0); s++) {
                        line.append(' ');
                    }
                }
                line.append(words[i]);
            }
        }
        while (line.length() < maxWidth) {
            line.append(' ');
        }
        return line.toString();
    }
}
